fn evKeep(self: *Conn, msg: []u8) void { self.lck(); defer self.unl(); if (self.evts.items.len >= CF.evmx or self.evby + msg.len > CF.evby) { self.gpaz.free(msg); self.evdr += 1; return; } self.evby += msg.len; self.evts.append(self.gpaz, msg) catch self.gpaz.free(msg); }
