pub fn call(self: *Conn, allo: std.mem.Allocator, method: []const u8, params: []const u8, mill: u32) ![]u8 { if (self.clsd.load(.acquire)) return error.Closed; const idz = self.nid; self.nid += 1; const req = try std.fmt.allocPrint(allo, "{{\"id\":{d},\"method\":\"{s}\",\"params\":{s}}}", .{ idz, method, if (params.len == 0) "{}" else params }); defer allo.free(req); try self.sendRaw(1, req); var pre: [32]u8 = undefined; const head = std.fmt.bufPrint(&pre, "{{\"id\":{d},", .{idz}) catch unreachable; const deadl = nowMs(self.iozz) + mill; while (true) { self.lck(); var hit: ?usize = null; for (self.resp.items, 0..) |msg, ix| { if (mem.startsWith(u8, msg, head)) { hit = ix; break; } } if (hit) |ix| { const msg = self.resp.orderedRemove(ix); self.unl(); defer self.gpaz.free(msg); return allo.dupe(u8, msg); } self.unl(); if (self.clsd.load(.acquire)) return error.Closed; if (nowMs(self.iozz) > deadl) return error.Timeout; self.nap(); } }
pub fn callJson(self: *Conn, aren: std.mem.Allocator, method: []const u8, params: []const u8, mill: u32) !std.json.Value { const msg = try self.call(aren, method, params, mill); const valu = std.json.parseFromSliceLeaky(std.json.Value, aren, msg, .{ .allocate = .alloc_always }) catch return error.CdpError; if (valu != .object) return error.CdpError; if (valu.object.get("error") != null) return error.CdpError; return valu.object.get("result") orelse .null; }
pub fn evWait(self: *Conn, aren: std.mem.Allocator, method: []const u8, from: *usize, mill: u32) !?[]const u8 { var pat: [96]u8 = undefined; const need = std.fmt.bufPrint(&pat, "\"method\":\"{s}\"", .{method}) catch return null; const deadl = nowMs(self.iozz) + mill; while (true) { self.lck(); while (from.* < self.evts.items.len) { const msg = self.evts.items[from.*]; from.* += 1; if (mem.find(u8, msg[0..@min(msg.len, 160)], need) != null) { const cp = aren.dupe(u8, msg) catch { self.unl(); return error.OutOfMemory; }; self.unl(); return cp; } } self.unl(); if (self.clsd.load(.acquire)) return error.Closed; if (nowMs(self.iozz) > deadl) return null; self.nap(); } }
pub fn close(self: *Conn) void { self.stop.store(true, .release); self.strm.shutdown(self.iozz, .both) catch {}; if (self.thrd) |thr| thr.join(); for (self.evts.items) |msg| self.gpaz.free(msg); self.evts.deinit(self.gpaz); for (self.resp.items) |msg| self.gpaz.free(msg); self.resp.deinit(self.gpaz); self.strm.close(self.iozz); self.gpaz.free(self.rbuf); self.gpaz.free(self.wbuf); const gpaz = self.gpaz; gpaz.destroy(self); } };
pub fn nowMs(iozz: std.Io) i64 { return @intCast(std.Io.Clock.awake.now(iozz).toMilliseconds()); }
fn dogz(self: *Conn) void { while (!self.dstp.load(.acquire)) { std.Io.sleep(self.iozz, .fromMilliseconds(25), .awake) catch {}; const dlz = self.dead.load(.acquire); if (dlz != 0 and nowMs(self.iozz) > dlz) { self.strm.shutdown(self.iozz, .both) catch {}; self.dead.store(0, .release); } } }
pub fn connect(gpaz: std.mem.Allocator, iozz: std.Io, port: u16, path: []const u8, mill: u32) !*Conn { var addr = try net.IpAddress.parse("127.0.0.1", port); const strm = try addr.connect(iozz, .{ .mode = .stream }); errdefer strm.close(iozz); const rbuf = try gpaz.alloc(u8, CF.bufz); errdefer gpaz.free(rbuf); const wbuf = try gpaz.alloc(u8, CF.bufz); errdefer gpaz.free(wbuf); const self = try gpaz.create(Conn); errdefer gpaz.destroy(self); self.* = .{ .gpaz = gpaz, .iozz = iozz, .strm = strm, .rdr = strm.reader(iozz, rbuf), .wrt = strm.writer(iozz, wbuf), .rbuf = rbuf, .wbuf = wbuf }; self.dead.store(nowMs(iozz) + mill, .release); const dog = try std.Thread.spawn(.{}, dogz, .{self}); var okay = false; defer { self.dstp.store(true, .release); dog.join(); if (!okay) self.dead.store(0, .release); }
var keyb: [16]u8 = undefined; iozz.random(&keyb); var k64: [24]u8 = undefined; _ = std.base64.standard.Encoder.encode(&k64, &keyb); const req = try std.fmt.allocPrint(gpaz, "GET {s} HTTP/1.1\r\nHost: 127.0.0.1:{d}\r\nUpgrade: websocket\r\nConnection: Upgrade\r\nSec-WebSocket-Key: {s}\r\nSec-WebSocket-Version: 13\r\n\r\n", .{ path, port, &k64 }); defer gpaz.free(req); self.wrt.interface.writeAll(req) catch return error.BadHandshake; self.wrt.interface.flush() catch return error.BadHandshake;
